function renderGcpNearbyMap(){
  const host=content.querySelector('[data-gcp-nearby-map]');if(!host)return;
  const taskId=host.dataset.taskId,detail=state.taskDetails[taskId],workspace=gcpWorkspace(taskId),images=detail?.gcp?.candidates||[],point=(detail?.gcp?.points||[]).find(item=>item.id===workspace.pointId);
  if(!point){host.innerHTML='<p class="form-note">Select a control point to show nearby camera positions.</p>';return}
  const valid=images.filter(image=>Number.isFinite(image.latitude)&&Number.isFinite(image.longitude));
  if(!valid.length){host.innerHTML='<p class="form-note">No geotagged photos fall within the selected search radius.</p>';return}
  const map=L.map(host,{zoomControl:true,attributionControl:true,scrollWheelZoom:true}).setView([point.latitude,point.longitude],19);gcpNearbyMap=map;
  L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:20,attribution:'Tiles © Esri'}).addTo(map);
  const bounds=L.latLngBounds([[point.latitude,point.longitude]]);
  const tooltip=(label)=>{const node=document.createElement('span');node.textContent=label;return node};
  L.circleMarker([point.latitude,point.longitude],{radius:9,color:'#fff',weight:2,fillColor:'#ee5007',fillOpacity:1}).addTo(map).bindTooltip(tooltip(`GCP · ${gcpPointName(point)}`));
  for(const image of valid){const selected=workspace.activeImage?.id===image.id,marker=L.circleMarker([image.latitude,image.longitude],{radius:selected?8:6,color:'#fff',weight:2,fillColor:selected?'#20a36a':'#1688d4',fillOpacity:.95}).addTo(map);marker.bindTooltip(tooltip(`${gcpImageName(image)} · ${(image.distanceM/0.3048).toFixed(1)} ft`));marker.on('click',()=>void openGcpImage(taskId,image.id));bounds.extend([image.latitude,image.longitude]);}
  map.fitBounds(bounds.pad(.18),{maxZoom:20});
}

function outputDownloadMenu(output){
  if(!output)return toast('This output is no longer available',true);
  const products=Array.isArray(output.downloadProducts)?output.downloadProducts:[];
  openModal(`Download · ${output.displayName||'Task products'}`,`<p class="form-note">Choose a product. Downloads stream directly to your browser; model files are not buffered in Viewer memory.</p><div class="product-download-list">${products.map((product,index)=>`<button class="product-download-item secondary-button" data-product-index="${index}"><span><strong>${esc(product.label)}</strong><small>${esc(product.format)} · ${esc(bytes(product.byteSize))}</small></span><span aria-hidden="true">↓</span></button>`).join('')||empty('No registered downloadable products are available. Refresh the workspace if this model was just prepared.')}<p class="form-note">Only existing registered files are listed. Streaming tile manifests are not original point-cloud files. OBJ geometry does not include its texture dependencies.</p></div>`);
  modalContent.querySelectorAll('[data-product-index]').forEach(element=>element.onclick=async()=>{
    const product=products[Number(element.dataset.productIndex)];
    if(!product?.grantUrl)return;
    element.disabled=true;
    try{await authenticatedDownload(product.grantUrl,product.fileName);toast('Download handed to your browser. Check its Downloads panel for progress.');}
    catch(error){toast(error.message,true)}finally{element.disabled=false}
  });
}

