function taskDetail(task,dataset){const detail=state.taskDetails[task.id],attempt=detail?.task?.latestAttempt||task.latestAttempt||{},metrics=detail?.task?.metrics||task.metrics||{},storage=detail?.storage?.task,outputs=detail?.task?.outputs||state.outputs.filter(output=>output.taskId===task.id),units=state.adminSession?.displayUnits||'imperial',projectActive=state.projects.find(project=>project.id===task.projectId)?.status==='active',readOnly=task.status==='archived'||!projectActive;if(detail?.loading)return`<div class="task-detail">${empty('Loading task details…')}</div>`;const controls=readOnly?`<p class="form-note">This ${task.status==='archived'?'task':'project'} is archived and read-only.</p>`:`<div class="row-actions task-lifecycle">${can('viewer.processing.write')?`${button('edit-task',task.id,'Rename')}${activeTaskAction(task,attempt)}${!LIVE_ATTEMPT_STATUSES.has(attempt.status)?dangerButton('trash-task',task.id,'Delete'):''}`:''}</div>`,datasetControls=dataset&&!readOnly&&datasetActions(dataset,projectActive)?`<div class="linked-dataset-actions"><p class="form-note">Dataset</p><div class="row-actions">${datasetActions(dataset,projectActive)}</div></div>`:'',status=heldSubmission(attempt)?'held_for_inspection':metrics.processingStatus||attempt.status||task.status,outputCount=metrics.outputCount??outputs.length,diskUsage=metrics.taskDiskUsageBytes==null?(storage?.totalBytes===undefined?null:bytes(storage.totalBytes)):bytes(metrics.taskDiskUsageBytes),gcp=detail?.gcp||{sets:[]},gcpCount=(gcp.sets||[]).reduce((sum,set)=>sum+(Number(set.pointCount)||0),0),running=LIVE_ATTEMPT_STATUSES.has(attempt.status);return`<div class="task-detail compact-task-detail"><section class="task-overview"><div class="task-overview-grid"><div><dl class="task-facts">${taskFact('Average GSD',metrics.averageGsdM==null?null:formatGsd(metrics.averageGsdM,units))}${taskFact('Surveyed area',metrics.surveyedAreaM2==null?null:formatArea(metrics.surveyedAreaM2,units))}${taskFact('Reconstructed points',metrics.reconstructedPointCount)}${taskFact('Georeferencing CRS',metrics.georeferencingCrs)}${taskFact('Task disk usage',diskUsage)}</dl><p class="form-note task-authority-note">Figures shown as Unavailable were not recorded for this run.</p>${readOnly?controls:activeTaskAction(task,attempt)}</div>${orthophotoPreview(task,outputs)}</div>${state.taskPage==='overview'?'':`<div class="task-open-page">${button('task-overview',task.id,'Open task page')}</div>`}</section>${running?logPanel(task,detail?.attempt||attempt,detail?.logs||[]):''}</div>`}
function taskWorkspaceBody(task,dataset){const detail=state.taskDetails[task.id],attempt=detail?.task?.latestAttempt||task.latestAttempt||{},metrics=detail?.task?.metrics||task.metrics||{},storage=detail?.storage?.task,outputs=detail?.task?.outputs||state.outputs.filter(output=>output.taskId===task.id),units=state.adminSession?.displayUnits||'imperial',projectActive=state.projects.find(project=>project.id===task.projectId)?.status==='active',readOnly=task.status==='archived'||!projectActive;if(detail?.loading)return`<div class="task-detail">${empty('Loading task details…')}</div>`;const controls=readOnly?`<p class="form-note">This ${task.status==='archived'?'task':'project'} is archived and read-only.</p>`:`<div class="row-actions task-lifecycle">${can('viewer.processing.write')?`${button('edit-task',task.id,'Rename')}${activeTaskAction(task,attempt)}${!LIVE_ATTEMPT_STATUSES.has(attempt.status)?dangerButton('trash-task',task.id,'Move task to Recycle Bin'):''}`:''}</div>`,datasetControls=dataset&&!readOnly&&datasetActions(dataset,projectActive)?`<div class="linked-dataset-actions"><p class="form-note">Dataset</p><div class="row-actions">${datasetActions(dataset,projectActive)}</div></div>`:'',status=heldSubmission(attempt)?'held_for_inspection':metrics.processingStatus||attempt.status||task.status,outputCount=metrics.outputCount??outputs.length,diskUsage=metrics.taskDiskUsageBytes==null?(storage?.totalBytes===undefined?null:bytes(storage.totalBytes)):bytes(metrics.taskDiskUsageBytes),gcp=detail?.gcp||{sets:[]},gcpCount=(gcp.sets||[]).reduce((sum,set)=>sum+(Number(set.pointCount)||0),0),running=LIVE_ATTEMPT_STATUSES.has(attempt.status);if(state.taskPage==='overview')return taskDetail(task,dataset);if(state.taskPage==='runs')return taskRunsPanel(task);if(state.taskPage==='gcp')return can('viewer.gcp.read')&&!readOnly?gcpPanel(task,dataset,gcp):empty('Ground-control editing is unavailable for this task or permission.');if(state.taskPage==='files')return outputPanel(task,attempt,outputs,!readOnly);return`<dl class="task-options">${taskFact('Task ID',task.id)}${taskFact('Created',dateTime(task.createdAt))}${taskFact('Dataset',dataset?.displayName||null)}${taskFact('Source images',metrics.sourceImageCount)}${taskFact('Processing duration',metrics.processingDurationMs==null?duration(attempt):durationFromMs(metrics.processingDurationMs))}${taskFact('Provider',state.providers.find(provider=>provider.id===attempt.providerId)?.displayName||null)}${taskFact('Preset',state.presets.find(preset=>preset.id===attempt.presetId)?.displayName||'Provider defaults')}${taskFact('Outputs',outputCount?`${outputCount} available`:'Unavailable')}${taskFact('Status',String(status||'unknown').replaceAll('_',' '))}</dl>${logPanel(task,detail?.attempt||attempt,detail?.logs||[])}${controls}${!readOnly?`<section class="task-streaming-settings"><h3>Streaming and product recovery</h3><div class="row-actions">${outputs.map(output=>lodAction(output)).join('')||'<p class="form-note">No streaming actions are needed.</p>'}</div></section>`:''}${datasetControls}`}
function workspaceBreadcrumb(project,task=null){const organization=project?.organizationId?state.hierarchy?.organizations?.find(item=>item.id===project.organizationId):null;const crumbs=[`<li><button type="button" class="breadcrumb-link" data-section="dashboard">Projects</button></li>`];if(organization)crumbs.push(`<li><span>${esc(organization.displayName)}</span></li>`);if(project)crumbs.push(task?`<li><button type="button" class="breadcrumb-link" data-action="task-return" data-id="${esc(task.id)}">${esc(project.displayName)}</button></li>`:`<li aria-current="page"><span>${esc(project.displayName)}</span></li>`);if(task)crumbs.push(`<li aria-current="page"><span>${esc(task.displayName)}</span></li>`);return`<nav class="workspace-breadcrumb" aria-label="Breadcrumb"><ol>${crumbs.join('')}</ol></nav>`}
function taskRunsPanel(task){const detail=state.taskDetails[task.id]||{},attempt=detail.task?.latestAttempt||task.latestAttempt||{},readOnly=task.status==='archived'||state.projects.find(project=>project.id===task.projectId)?.status!=='active';if(detail.loading)return`<div class="task-detail">${empty('Loading processing runs…')}</div>`;return`${attemptHistory(task.id,detail.attempts||[],attempt.id,!readOnly).replace('<details ','<details open ')}<p class="form-note task-runs-note">Runs across every project are in <button type="button" class="text-button" data-section="diagnostics">Diagnostics</button>.</p>`}
function taskWorkspacePage(){const task=state.tasks.find(item=>item.id===state.expandedTaskId);if(!task)return empty('Task unavailable.');const dataset=state.datasets.find(item=>item.id===task.datasetId);const project=state.projects.find(item=>item.id===task.projectId),tab=(action,panel,label)=>button(action,task.id,label,state.taskPage===panel,state.taskPage===panel?'aria-current="page"':'');return`${workspaceBreadcrumb(project,task)}<div class="section-heading task-page-heading"><div><h2>${esc(task.displayName)}</h2><p class="form-note">${esc(project?.displayName||'')}</p></div>${button('task-return',task.id,'Back to project')}</div><nav class="task-page-navigation" aria-label="Task sections">${tab('task-overview','overview','Overview')}${tab('task-runs','runs','Runs')}${tab('task-settings','settings','Details & processing')}${tab('task-files','files','Files & versions')}${can('viewer.gcp.read')?tab('task-gcp','gcp','Ground control points'):''}</nav><section class="task-workspace-page">${taskWorkspaceBody(task,dataset)}</section>`}
function attemptLabel(item,currentId){return`Run #${available(item.attemptNumber||item.attempt_number||'?')}${item.id===currentId?' · current':''}`}
function stageName(value){return String(value||'unknown').replaceAll('_',' ').replaceAll('.',' › ')}
function diagnosticJobLines(job){const lines=[job.result?.summary||job.summary||job.errorMessage||job.result?.error||'No additional detail'];if(job.queueReason)lines.push(`Queue: ${stageName(job.queueReason)}`);if(job.availableAt)lines.push(`Available: ${dateTime(job.availableAt)}`);if(job.heartbeatAt)lines.push(`Heartbeat: ${dateTime(job.heartbeatAt)}`);if(Number.isFinite(job.attemptCount))lines.push(`Worker attempts: ${job.attemptCount}`);if(job.input){lines.push(`Derivative input: ${bytes(job.input.byteSize)} across ${job.input.fileCount} files · limit ${bytes(job.input.limitBytes)} · reserved ${bytes(job.input.reservationBytes)}`);const roles=Object.entries(job.input.roleBreakdown||{}).map(([role,value])=>`${stageName(role)} ${value.fileCount} / ${bytes(value.byteSize)}`);if(roles.length)lines.push(`Roles: ${roles.join(', ')}`)}const evidence=job.auditEvidence;if(evidence?.metric)lines.push(`Audit: ${stageName(evidence.metric)} observed ${evidence.observed} · limit ${evidence.limit}${evidence.grayZoneLimit===undefined?'':` · gray-zone ceiling ${evidence.grayZoneLimit}`}`);if(evidence?.acceptance)lines.push(`Audit acceptance: ${stageName(evidence.acceptance)}${evidence.policyRevision?` · ${evidence.policyRevision}`:''}`);return lines}
function attemptDiagnosticPanel(diagnostic,item,panelId,retryAction,retryAttributes=''){if(!diagnostic)return'';if(diagnostic.loading)return`<div class="attempt-diagnostic" id="${esc(panelId)}" role="status">Loading run diagnostics…</div>`;if(diagnostic.error)return`<div class="attempt-diagnostic load-error" id="${esc(panelId)}" role="alert"><strong>Run diagnostics could not be loaded</strong><p>${esc(diagnostic.error)}</p>${button(retryAction,item.id,'Retry',false,`${retryAttributes} aria-controls="${esc(panelId)}"`)}</div>`;const events=diagnostic.events||[],jobs=[...(diagnostic.processingJobs||[]),...(diagnostic.derivativeJobs||diagnostic.derivatives||[]),...(diagnostic.operations||[])],failure=diagnostic.errorDetail||events.find(event=>(event.state||event.status)==='failed'||event.severity==='error')||item.errorMessage&&{errorCode:item.errorCode,errorMessage:item.errorMessage,stage:item.status},logs=diagnostic.logs||[];return`<div class="attempt-diagnostic" id="${esc(panelId)}"><div class="attempt-diagnostic-grid">${failure?`<section class="diagnostic-error" role="alert"><p class="eyebrow">Failure details</p><strong>${esc(failure.errorCode||failure.code||'processing_failed')}</strong><p>${esc(failure.errorMessage||failure.summary||failure.message||item.errorMessage||'This run failed without a diagnostic summary.')}</p><small>Stage: ${esc(stageName(failure.stage||failure.phase||failure.type||item.status))}${failure.diagnosticId?` · Diagnostic ID: ${esc(failure.diagnosticId)}`:''}</small></section>`:''}<section><h4>Stage timeline</h4><ol class="stage-timeline">${events.map(event=>{const eventState=event.state||event.status||(event.severity==='error'?'failed':event.severity==='warning'?'warning':'progress');return`<li class="${esc(eventState)}"><span aria-hidden="true"></span><div><strong>${esc(stageName(event.stage||event.phase||event.type||event.eventType))}</strong><small>${dateTime(event.createdAt)} · ${esc(stageName(eventState))}</small>${event.summary||event.message?`<p>${esc(event.summary||event.message)}</p>`:''}${typeof event.details?.reason==='string'?`<p>Cleanup reason: ${esc(event.details.reason)}</p>`:''}</div></li>`}).join('')||`<li><div><strong>No stage events recorded</strong><small>The run state is ${esc(stageName(item.status))}.</small></div></li>`}</ol></section><section><h4>Jobs and derivatives</h4><div class="diagnostic-job-list">${jobs.map(job=>`<div><strong>${esc(stageName(job.type||job.jobType||job.operationType))}</strong>${badge(job.status)}${diagnosticJobLines(job).map(line=>`<small>${esc(line)}</small>`).join('')}</div>`).join('')||empty('No job details were recorded for this run.')}</div></section></div><section class="attempt-log-section"><h4>Sanitized run output</h4>${logs.length?`<pre class="log-tail">${esc(logs.map(log=>`[${log.createdAt||''}] ${String(log.level||'info').toUpperCase()} ${log.message||''}`).join('\n'))}</pre>`:empty('No retained log output for this run.')}${diagnostic.logsTruncated?`<p class="form-note">Older output is unavailable because this log was truncated or aged out after ${esc(diagnostic.logRetentionDays||'the configured retention period')}.</p>`:''}</section></div>`}
function attemptHistory(taskId,attempts,currentId,allowRetry=true){const detail=state.taskDetails[taskId]||{},more=Boolean(detail.nextAttemptCursor);return`<details class="task-subsection task-disclosure attempt-history" ${disclosureAttributes(taskId,'history')}><summary><span>Processing history (${attempts.length}${more?'+':''})</span><small>Every recorded run</small></summary><div class="task-disclosure-body data-list">${attempts.map(item=>{const selected=detail.selectedAttemptId===item.id,panelId=`attempt-diagnostic-${item.id}`,providerRetry=Boolean(item.providerId);return`<article class="attempt-run ${selected?'selected':''}" data-attempt-id="${esc(item.id)}"><div class="attempt-run-heading"><div><strong>${attemptLabel(item,currentId)}</strong><small>${dateTime(item.createdAt)} · ${duration(item)}${item.providerTaskId?` · Provider task ${esc(item.providerTaskId)}`:''}</small>${item.errorMessage?`<small class="attempt-error-summary">${esc(item.errorCode||'processing_failed')}: ${esc(item.errorMessage)}</small>`:''}${!providerRetry&&['failed','cancelled'].includes(item.status)?'<small>Imported runs are retried from their owning import or required-derivative operation.</small>':''}</div>${badge(attemptStatusLabel(item))}<div class="row-actions">${button('open-attempt-diagnostics',item.id,selected?'Hide details':'View diagnostics',false,`data-task-id="${esc(taskId)}" aria-expanded="${selected}" aria-controls="${esc(panelId)}"`)}${allowRetry&&providerRetry&&can('viewer.processing.write')&&['failed','cancelled'].includes(item.status)?button('retry-attempt',item.id,'Retry provider run'):''}</div></div>${selected?attemptDiagnosticPanel(detail.attemptDiagnostics?.[item.id],item,panelId,'retry-attempt-diagnostics',`data-task-id="${esc(taskId)}"`):''}</article>`}).join('')||empty('No processing attempts have been recorded.')}${more?`<div class="history-load-more">${button('load-more-attempts',taskId,'Load older runs')}</div>`:''}</div></details>`}
function durationFromMs(value){const total=Math.max(0,Math.round(Number(value)/1000)),hours=Math.floor(total/3600),minutes=Math.floor(total%3600/60);return hours?`${hours}h ${minutes}m`:`${minutes}m ${total%60}s`}
function activeTaskAction(task,attempt){if(!can('viewer.processing.write')||task.status==='archived')return'';if(LIVE_ATTEMPT_STATUSES.has(attempt.status))return heldSubmission(attempt)?button('held-attempt',attempt.id,'Held for inspection',false,'disabled title="Verify the original provider task before taking action."'):button('cancel-attempt',attempt.id,'Cancel');if(attempt.providerId&&['failed','cancelled'].includes(attempt.status))return button('retry-attempt',attempt.id,'Restart provider run',true);if(attempt.providerId)return button('restart-task',task.id,'Restart',false);return''}
function gcpWorkspace(taskId){return state.gcpWorkspaces[taskId]||(state.gcpWorkspaces[taskId]={setId:null,pointId:null,mode:'radius',radiusFeet:50,activeImage:null,imageUrl:null,draftPixel:null,editingId:null,pointCache:{}})}
function gcpImageName(image){return String(image?.relativePath||image?.id||'Image').split('/').at(-1)}
