function takeGcpImportDraft(){
  if(!state.token||!can('viewer.gcp.write'))return null;
  const form=content.querySelector?.('.gcp-import-form');if(!form)return null;
  const task=state.tasks.find(item=>item.id===form.dataset.taskId);
  if(!task||task.datasetId!==form.dataset.datasetId)return null;
  const focused=form.contains?.(document.activeElement)?document.activeElement:null;
  let selection=null;try{if(focused&&typeof focused.selectionStart==='number')selection=[focused.selectionStart,focused.selectionEnd,focused.selectionDirection];}catch{}
  const draft={form,focused,selection,token:state.token,taskId:task.id,datasetId:task.datasetId,open:Boolean(form.closest('details')?.open)};
  form.remove();return draft;
}
function restoreGcpImportDraft(draft){
  if(!draft||state.token!==draft.token||!can('viewer.gcp.write'))return;
  if(!state.tasks.some(item=>item.id===draft.taskId&&item.datasetId===draft.datasetId))return;
  const target=[...content.querySelectorAll('.gcp-import-form')].find(form=>form.dataset.taskId===draft.taskId&&form.dataset.datasetId===draft.datasetId);
  if(!target)return;const details=target.closest('details');target.replaceWith(draft.form);if(details)details.open=draft.open;
  if(draft.focused){try{draft.focused.focus({preventScroll:true});if(draft.selection)draft.focused.setSelectionRange(...draft.selection);}catch{}}
}
