async function setProjectCustomer(projectId){
  const project=state.projects.find(item=>item.id===projectId);
  if(!project||!canManageHierarchy(state.hierarchy,can))return;
  const organizations=assignableOrganizations(state.hierarchy);
  const currentOrganization=state.hierarchy?.organizations?.find(item=>item.id===project.organizationId);
  if(currentOrganization&&currentOrganization.status!=='active'&&!organizations.some(item=>item.id===currentOrganization.id))organizations.push(currentOrganization);
  if(project.organizationId&&!currentOrganization)organizations.push({id:project.organizationId,displayName:'Current customer (not loaded)',status:'unknown'});
  if(!organizations.length&&!project.organizationId){toast('Add a customer first, from Customers on the Projects page.',true);return}

  const chosen=await dialogs.form({
    title:`Set customer for ${project.displayName}`,
    message:'This only changes where the project appears in the list. It does not change who can see its models.',
    fields:[{name:'organizationId',label:'Customer',value:project.organizationId||'',options:[
      {value:'',label:'No customer (Unassigned)'},
      ...organizations.map(item=>({value:item.id,label:item.id===project.organizationId&&!currentOrganization?'Current customer (not loaded)':item.status==='active'?item.displayName:`${item.displayName} (archived current assignment)`})),
    ]}],
    submitLabel:'Next',
  });
  if(!chosen)return;

  const selectedOrganization=state.hierarchy?.organizations?.find(item=>item.id===chosen.organizationId);
  const currentGroupRecord=state.hierarchy?.groups?.find(item=>item.id===project.groupId&&item.organizationId===project.organizationId);
  const archivedCurrentCustomer=chosen.organizationId===project.organizationId&&selectedOrganization?.status!=='active';
  const groups=chosen.organizationId&&!archivedCurrentCustomer?assignableGroups(state.hierarchy,chosen.organizationId):[];
  let groupId='';
  let groupOptions=[{value:'',label:'No group'},...groups.map(item=>({value:item.id,label:item.displayName}))];
  const currentGroupBelongsToCustomer=chosen.organizationId===project.organizationId&&currentGroupRecord;
  const currentGroupUnloaded=Boolean(project.groupId&&chosen.organizationId===project.organizationId&&!currentGroupRecord);
  if(archivedCurrentCustomer&&currentGroupBelongsToCustomer){
    groupId=currentGroupRecord.id;
    groupOptions=[{value:groupId,label:`${currentGroupRecord.displayName} (${currentGroupRecord.status==='active'?'current group; customer archived':'archived current assignment'})`}];
  }else if(currentGroupBelongsToCustomer&&currentGroupRecord.status!=='active'){
    groupId=currentGroupRecord.id;
    groupOptions.push({value:groupId,label:`${currentGroupRecord.displayName} (archived current assignment)`});
  }else if(currentGroupBelongsToCustomer&&groups.some(item=>item.id===currentGroupRecord.id)){
    groupId=currentGroupRecord.id;
  }else if(currentGroupUnloaded){
    groupId=project.groupId;
    groupOptions.push({value:groupId,label:'Current group (not loaded)'});
  }
  if(groups.length||currentGroupBelongsToCustomer||currentGroupUnloaded){
    const picked=await dialogs.form({title:'Choose a group',fields:[{name:'groupId',label:'Group',value:groupId,options:groupOptions}],submitLabel:'Save'});
    if(!picked)return;
    groupId=picked.groupId;
  }else if(archivedCurrentCustomer){
    groupId=project.groupId||'';
  }

  const nextOrganizationId=chosen.organizationId||null;
  const nextGroupId=nextOrganizationId&&groupId?groupId:null;
  if(nextOrganizationId===(project.organizationId||null)&&nextGroupId===(project.groupId||null)){toast('No change made');return}
  await hierarchyWrite(`/api/v1/projects/${encodeURIComponent(project.id)}/hierarchy`,'PATCH',assignmentBody(project,chosen.organizationId,groupId),chosen.organizationId?'Customer set':'Customer cleared');
}
