addEventListener('popstate',()=>{releaseAllGcpImages();applyWorkspaceView(readWorkspaceView());validateWorkspaceView();render();hydrateExpandedTask()});
let bootAuthority=workspaceBootstrapAuthority();
try{
  const recovered=await resumeCurrentTabWorkspaceRecovery({accessToken:state.token,install:envelope=>{requireBootstrapAuthority(bootAuthority);installWorkspaceSession(envelope);bootAuthority=workspaceBootstrapAuthority();},restoreView:view=>{requireBootstrapAuthority(bootAuthority);if(view)applyWorkspaceView(view);syncWorkspaceView('replace');}});
  requireBootstrapAuthority(bootAuthority);
  if(!recovered&&relayWorkspaceRecoveryGrant()){}else{
    const redeemed=recovered||await redeemGrant();bootAuthority=workspaceBootstrapAuthority();
    if(!redeemed&&state.token){await restoreWorkspaceSession();bootAuthority=workspaceBootstrapAuthority();}
    if(state.token)await load();else{renderNav();access()}
  }
}catch(error){
  if(bootAuthority===workspaceBootstrapAuthority()){
    if(error.fatal||error.status===401||!state.token)clearWorkspaceAuthorization('revoked');
    else{try{if(!workspaceRenewal){await restoreWorkspaceSession();bootAuthority=workspaceBootstrapAuthority();}}catch(currentError){if(bootAuthority===workspaceBootstrapAuthority()&&currentError.status===401)clearWorkspaceAuthorization()}
      if(bootAuthority===workspaceBootstrapAuthority()&&state.token){renderNav();toast('Viewer session renewal is temporarily unavailable; your current session was preserved',true);await load()}}
  }
}
